/bin/zsh -lc "python3.12 - <<'PY'
from solution import reconcile
import random

assert reconcile(iter(())) == {}
assert reconcile(iter([
    {'entity': 'a', 'version': 5, 'deleted': True},
    {'entity': 'a', 'version': 4, 'payload': 'stale'},
])) == {}
assert reconcile(iter([
    {'entity': 'a', 'version': 5, 'deleted': True},
    {'entity': 'a', 'version': 6, 'payload': None},
])) == {'a': None}
for first, second in [(False, False), (False, True), (True, False), (True, True)]:
    events = [{'entity': 'a', 'version': 0, 'deleted': d, 'payload': i}
              for i, d in enumerate((first, second))]
    assert reconcile(iter(events)) == ({} if second else {'a': 1})
for payload in (None, False, 0, '', [], {}, {'nested': [0, None]}):
    assert reconcile(iter([{'entity': ' ', 'version': 0, 'payload': payload}])) == {' ': payload}
assert reconcile([{'entity': e, 'version': 0, 'payload': e} for e in ('a', 'A', ' a')]) == {e: e for e in ('a', 'A', ' a')}
invalid = [None, [], 'event', {}, {'entity': 'a'}, {'version': 0},
           {'entity': '', 'version': 0, 'payload': 1},
           {'entity': 1, 'version': 0, 'payload': 1}]
invalid += [{'entity': 'a', 'version': v, 'payload': 1} for v in (True, False, -1, 0.0, '0', None)]
invalid += [{'entity': 'a', 'version': 0, 'deleted': d, 'payload': 1} for d in (None, 0, 1, '', [])]
invalid += [{'entity': 'a', 'version': 0}]
for bad in invalid:
    for prefix in ([], [{'entity': 'a', 'version': 100, 'payload': 'winner'}]):
        try:
            reconcile(iter(prefix + [bad]))
        except ValueError:
            pass
        else:
            raise AssertionError(('accepted invalid event', bad))
payload = {'nested': [[]]}
events = [{'entity': 'a', 'version': 0, 'payload': payload, 'ignored': object()}]
result = reconcile(iter(events))
result['a']['nested'][0].append('result')
assert payload == {'nested': [[]]}
payload['nested'].append('input')
assert result == {'a': {'nested': [['result']]}}
cycle = []
cycle.append(cycle)
out = reconcile([{'entity': 'cycle', 'version': 0, 'payload': cycle}])['cycle']
assert out is not cycle and out[0] is out
rng = random.Random(42)
for _ in range(500):
    events = [{'entity': rng.choice(['a', 'A', ' ']), 'version': rng.randrange(8),
               'deleted': rng.choice([False, True]), 'payload': i} for i in range(rng.randrange(40))]
    expected = {}
    for entity in {e['entity'] for e in events}:
        _, winner = max(((i, e) for i, e in enumerate(events) if e['entity'] == entity),
                        key=lambda pair: (pair[1]['version'], pair[0]))
        if not winner['deleted']:
            expected[entity] = winner['payload']
    assert reconcile(iter(events)) == expected
print('Additional checks passed: validation, stale events, ties, tombstones, revival, payload isolation, cycles, and 500 randomized streams.')
PY"
